def solve(gi):
    H,W=len(gi),len(gi[0])
    cc=collections.Counter(v for r_ in gi for v in r_)
    bg=cc.most_common(1)[0][0]
    others=[c for c in sorted(set(cc)-{bg}) if cc[c]<H*W//2]
    mc=min(others,key=lambda c:cc[c]); bc=[c for c in others if c!=mc][0]
    def comps(c):
        seen=set(); out=[]
        for i in range(H):
            for j in range(W):
                if gi[i][j]==c and (i,j) not in seen:
                    st=[(i,j)]; comp=[]
                    while st:
                        p=st.pop()
                        if p in seen: continue
                        seen.add(p); comp.append(p)
                        for x,y in ((p[0]+1,p[1]),(p[0]-1,p[1]),(p[0],p[1]+1),(p[0],p[1]-1)):
                            if 0<=x<H and 0<=y<W and gi[x][y]==c: st.append((x,y))
                    out.append(comp)
        return out
    bs=comps(bc)
    vert=all(len({j for i,j in s})==1 for s in bs)
    segs=sorted(bs,key=lambda s:min(i for i,j in s)) if vert else sorted(bs,key=lambda s:min(j for i,j in s))
    A,B=segs[0],segs[-1]
    # spans along the perpendicular axis
    if vert:
        spanA=(min(i for i,j in A),max(i for i,j in A)); spanB=(min(i for i,j in B),max(i for i,j in B))
        def span(s): return s
        def inside(x,s): return s[0]<=x<=s[1]
        def step(i,j,d): return (i+d,j)
    else:
        spanA=(min(j for i,j in A),max(j for i,j in A)); spanB=(min(j for i,j in B),max(j for i,j in B))
        def inside(x,s): return s[0]<=x<=s[1]
        def step(i,j,d): return (i,j+d)
    mks=sorted((i,j) for i in range(H) for j in range(W) if gi[i][j]==mc)
    out=[row[:] for row in gi]
    bcells={(i,j) for i in range(H) for j in range(W) if gi[i][j]==bc}
    for mi,mj in mks:
        # own ray: direction toward bar whose span contains mj (or mi if vert)
        if vert:
            src=mi
            cands=[s for s in (spanA,spanB) if inside(src,s)]
            d=1 if min(src,spanA[0])==src and min(src,spanB[0])==src else (1 if src>=spanA[1]>=spanB[0] else -1)
            tgt=max([s for s in (spanA,spanB) if inside(src,s)])
            d=1 if tgt==spanB else -1
            i_=src
            while True:
                ni,_=step(i_,mj,d)
                if not(0<=ni<H): break
                if (ni,mj) in bcells: break
                if out[ni][mj]==bg: out[ni][mj]=mc
                i_=ni
        else:
            src=mj
            cands=[s for s in (spanA,spanB) if inside(src,s)]
            tgt=max([s for s in (spanA,spanB) if inside(src,s)])
            d=1 if tgt==spanB else -1
            j_=src
            while True:
                ni,nj=step(mi,j_,d)
                if not(0<=nj<W): break
                if (mi,nj) in bcells: break
                if out[ni][nj]==bg: out[ni][nj]=mc
                j_=nj
        # mapped ray: reflect src index into other span
        if vert:
            if inside(src,spanA):
                o,bb=spanB,spanA
            else:
                o,bb=spanA,spanB
            idx=src-o[0]
            nb=o[0]+idx
            # full perpendicular extent, skipping bar cells
            lo,hi=min(mi,bb[0]),max(mi,bb[1])
            for ni in range(lo,hi+1):
                if (ni,nb) not in bcells and out[ni][nb]==bg: out[ni][nb]=mc
        else:
            if inside(src,spanA):
                o,bb=spanB,spanA
            else:
                o,bb=spanA,spanB
            idx=src-o[0]
            nb=o[0]+idx
            lo,hi=min(mi,bb[0]),max(mi,bb[1])
            for nj in range(lo,hi+1):
                if (nb,nj) not in bcells and out[nb][nj]==bg: out[nb][nj]=mc
    for mi,mj in mks:
        if out[mi][mj]!=mc and out[mi][mj]==bg: out[mi][mj]=4
    return out
