    mkcs={gi[i][j] for (i,j) in mk}
    # painted = non-bg cells changed
    painted=set()
    for (i,j) in mk: painted.add((i,j)); painted.add((i,j))
    chg={(p,go[p[0]][p[1]]) for p in product(range(H),range(W)) if gi[p[0]][p[1]]!=go[p[0]][p[1]]}
