    # report changed cells grouped by color
    byc={}
    for (i,j,v) in chg:
        if (i,j) in mk or v==4: byc.setdefault('special',{}).add(None)
        pass
    # classify painted lines: find maximal straight runs
    res=go
    for i in range(H):
        for j in range(W):
            if gi[i][j]!=res[i][j] and res[i][j] not in (4,):
                pass
    print('changed cells:',sorted(chg))
