def comps(gi,c):
    H,W=len(gi),len(gi[0])
    seen=[[False]*W for _ in range(H)]; out=[]
    for i in range(H):
        for j in range(W):
            if gi[i][j]==c and not seen[i][j]:
                st=[(i,j)]; seen[i][j]=True; cs=[]
                while st:
                    x,y=st.pop(); cs.append((x,y))
                    for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
                        nx,ny=x+dx,y+dy
                        if 0<=nx<H and 0<=ny<W and gi[nx][ny]==c and not seen[nx][ny]:
                            seen[nx][ny]=True; st.append((nx,ny))
                out.append(sorted(cs))
    return out
def is_segment(s):
    rs={p[0] for p in s}; cls={p[1] for p in s}
    return len(rs)==1 or len(cls)==1
def solve(gi):
    H,W=len(gi),len(gi[0])
    cc=collections.Counter(v for r_ in gi for v in r_)
    bg=cc.most_common(1)[0][0]
    def barinfo():
        for c in cc:
            if c==bg: continue
            s=comps(c)
            if len(s)==2 and all(is_segment(x) for x in s): return c,s
        return None,None
    bc,segs=barinfo()
    mk=[(i,j) for i in range(H) for j in range(W) if gi[i][j]!=bg and gi[i][j]!=bc]
    horiz = len({p[0] for p in segs[0]})==1
    res=[row[:] for row in gi]
    if horiz:
        src=min(segs,key=lambda s:min(p[0] for p in s)); dst=max(segs,key=lambda s:min(p[0] for p in s))
        for (i,j) in sorted(mk):
            k=max(j-src[0][1],0)
            kc=min(k,len(dst)-1)
            tc=sorted(dst,key=lambda p:p[1])[kc]
            ty=tc[0]
            for y in range(W):
                if gi[ty][y]==bg: res[ty][y]=mc:=None
            mc=gi[i][j]
            for y in range(W):
                if gi[ty][y]==bg: res[ty][y]=mc
            dy=-1 if min(p[0] for p in src)<i else 1
            x=i+dy
            while 0<=x<H and gi[x][j]==bg: res[x][j]=mc; x+=dy
            if src[0][0]<dst[0][0]:
                pass
    else:
        src=min(segs,key=lambda s:min(p[1] for p in s)); dst=max(segs,key=lambda s:min(p[1] for p in s))
        for (i,j) in sorted(mk):
            k=max(i-src[0][0],0)
            kc=min(k,len(dst)-1)
            tc=sorted(dst,key=lambda p:p[0])[kc]
            tx=tc[0]
            for x in range(H):
                if gi[x][tx]==bg: res[x][tx]=gi[i][j]
            dy=-1 if min(p[1] for p in src)<j else 1
            x=j+dy
            while 0<=x<W and gi[i][x]==bg: res[i][x]=gi[i][j]; x+=dy
    for (i,j) in mk: res[i][j]=4
    return res
for n in [1,2,3,4,5,6,7,8]:
    print(n, solve(G['Demo pair %d input'%n])==G['Demo pair %d output'%n])

